set-variable.value:
@{
        var u = context.Request.OriginalUrl;
        var qs = u.QueryString ?? "";
        return u.Scheme + "://" + u.Host + u.Path + qs;
    }

@{
        /* HMAC input = URL + concatenated sorted (key+value) pairs, per
           twilio-python RequestValidator.compute_signature. See the header
           comment for why pairs are SOH-packed and sorted ordinally. Use
           the char overload of IndexOf below — the string overload uses
           CurrentCulture collation, treats the SOH as ignorable, and
           returns 0. */
        var raw = context.Request.Body.As<string>(preserveContent: true) ?? string.Empty;
        char sepChar = (char)1;
        var pairs = new System.Collections.Generic.List<string>();
        foreach (var seg in raw.Split('&')) {
            if (!string.IsNullOrEmpty(seg)) {
                var eq = seg.IndexOf('=');
                string k;
                string v;
                if (eq >= 0) {
                    k = System.Net.WebUtility.UrlDecode(seg.Substring(0, eq));
                    v = System.Net.WebUtility.UrlDecode(seg.Substring(eq + 1));
                } else {
                    k = System.Net.WebUtility.UrlDecode(seg);
                    v = string.Empty;
                }
                pairs.Add(k + sepChar + v);
            }
        }
        pairs.Sort(System.StringComparer.Ordinal);  // ordinal, not the CurrentCulture default
        var sb = new System.Text.StringBuilder();
        sb.Append((string)context.Variables["twilioFullUrl"]);
        string prev = null;
        foreach (var p in pairs) {
            if (p != prev) {
                var idx = p.IndexOf(sepChar);
                sb.Append(p.Substring(0, idx));
                sb.Append(p.Substring(idx + 1));
                prev = p;
            }
        }
        return sb.ToString();
    }

@{
        var key = System.Text.Encoding.UTF8.GetBytes("{{TwilioAuthToken}}");
        using (var hmac = new System.Security.Cryptography.HMACSHA1(key)) {
            var bytes = System.Text.Encoding.UTF8.GetBytes((string)context.Variables["twilioSignedString"]);
            return Convert.ToBase64String(hmac.ComputeHash(bytes));
        }
    }

@{
        var raw = context.Request.Body.As<string>(preserveContent: true) ?? string.Empty;
        foreach (var seg in raw.Split('&')) {
            var eq = seg.IndexOf('=');
            if (eq < 0) {
                continue;
            }
            var k = System.Net.WebUtility.UrlDecode(seg.Substring(0, eq));
            if (k == "CallSid") {
                return System.Net.WebUtility.UrlDecode(seg.Substring(eq + 1));
            }
        }
        return string.Empty;
    }

inbound.set-body:
@{
        var raw = context.Request.Body.As<string>(preserveContent: false) ?? string.Empty;
        var dq = ((char)34).ToString();
        var bs = ((char)92).ToString();
        var sb = new System.Text.StringBuilder();
        sb.Append('{');
        bool first = true;
        foreach (var seg in raw.Split('&')) {
            if (string.IsNullOrEmpty(seg)) {
                continue;
            }
            var eq = seg.IndexOf('=');
            string k;
            string v;
            if (eq >= 0) {
                k = System.Net.WebUtility.UrlDecode(seg.Substring(0, eq));
                v = System.Net.WebUtility.UrlDecode(seg.Substring(eq + 1));
            } else {
                k = System.Net.WebUtility.UrlDecode(seg);
                v = string.Empty;
            }
            if (string.IsNullOrEmpty(v)) {
                continue;
            }
            k = k.Replace(bs, bs + bs).Replace(dq, bs + dq);
            v = v.Replace(bs, bs + bs).Replace(dq, bs + dq);
            if (!first) {
                sb.Append(',');
            }
            first = false;
            sb.Append(dq);
            sb.Append(k);
            sb.Append(dq);
            sb.Append(':');
            sb.Append(dq);
            sb.Append(v);
            sb.Append(dq);
        }
        sb.Append('}');
        return sb.ToString();
    }
